.game-screen{position:absolute;inset:0;z-index:4;display:none;pointer-events:none}.game-screen.active{display:block}.game-screen button{pointer-events:auto}.game-top{position:absolute;top:93px;left:5%;right:5%;display:flex;align-items:flex-start;gap:14px}.game-pause{width:37px;height:37px;border:1px solid #ffffff55;background:#071116aa;font-size:16px}.run-objective{width:180px;padding:4px 0}.run-objective small,.run-score small,.distance-box small,.run-coins small{display:block;color:#cad3cd;font-size:8px;letter-spacing:1.5px}.run-objective b{display:block;font:600 16px 'Barlow Condensed';margin:4px 0 7px}.run-objective>i{display:block;height:3px;background:#ffffff44}.run-objective>i span{display:block;width:0;height:100%;background:var(--acid)}.run-score{margin-left:auto;text-align:right}.run-score b{font:700 29px 'Barlow Condensed';display:block}.game-left{position:absolute;left:5%;top:40%;}.distance-box{background:#071116a8;padding:10px 13px;border-left:2px solid var(--orange)}.distance-box b{font:600 24px 'Barlow Condensed';display:block;margin-top:3px}.distance-box b i{font:500 9px 'DM Sans';font-style:normal;color:#aab8b1;margin-left:4px}.near-miss{margin-top:10px;color:var(--acid);font:800 12px 'Barlow Condensed';letter-spacing:1px;opacity:0;transform:translateX(-10px);transition:.2s}.near-miss.show{opacity:1;transform:translateX(0)}.near-miss b{font-size:10px}.game-bottom{position:absolute;left:5%;right:5%;bottom:22px;display:flex;align-items:flex-end;gap:25px}.speed-dial{height:88px;width:88px;border-radius:50%;border:2px solid rgba(255,255,255,.55);background:rgba(5,13,16,.67);box-shadow:inset 0 0 0 5px rgba(255,255,255,.07);display:flex;flex-direction:column;justify-content:center;align-items:center;position:relative}.speed-dial:before{content:'';position:absolute;inset:5px;border-radius:50%;border:1px dashed rgba(255,255,255,.22)}.speed-dial b{font:700 36px/.9 'Barlow Condensed'}.speed-dial small{font-size:7px;letter-spacing:1.5px;color:#c3ccc7}.speed-dial .gear-value{position:absolute;bottom:-10px;right:-7px;width:23px;height:23px;border-radius:50%;display:grid;place-items:center;background:var(--orange);font:700 11px 'Barlow Condensed';font-style:normal}.run-coins{display:flex;align-items:center;gap:6px;margin-bottom:8px}.run-coins .coin-icon{font-size:19px}.run-coins b{font:600 22px 'Barlow Condensed'}.run-coins small{font-size:7px;letter-spacing:1px;margin-left:4px}.nitro-wrap{width:165px;margin-bottom:8px}.nitro-label{display:flex;justify-content:space-between;font-size:8px;letter-spacing:1.2px;margin-bottom:6px}.nitro-label b{color:var(--acid)}.nitro-track{height:5px;background:#ffffff44}.nitro-track i{height:100%;width:100%;display:block;background:linear-gradient(90deg,#77e9ed,var(--acid));transition:width .1s}.nitro-wrap button{background:rgba(4,12,15,.72);border:1px solid rgba(214,255,98,.64);color:var(--acid);font-size:8px;letter-spacing:1.5px;padding:7px 10px;margin-top:8px}.nitro-wrap button span{font-size:13px;margin-left:9px}.touch-controls{margin-left:auto;display:flex;gap:12px}.touch-controls button{width:68px;height:66px;background:rgba(6,14,18,.5);border:1px solid rgba(255,255,255,.4);font-size:21px;color:#fff}.touch-controls button:active{background:rgba(255,100,56,.5)}.touch-controls small{display:block;font-size:7px;letter-spacing:1px;margin-top:5px;color:#c8d1cb}.game-toast{position:absolute;top:26%;left:50%;transform:translate(-50%,-10px);font:800 22px 'Barlow Condensed';letter-spacing:2px;color:var(--acid);text-shadow:0 2px 10px #000;opacity:0;transition:.3s}.game-toast.show{opacity:1;transform:translate(-50%,0)}.game-overlay{position:absolute;inset:0;background:rgba(3,10,13,.72);backdrop-filter:blur(8px);display:none;align-items:center;justify-content:center;pointer-events:auto}.game-overlay.visible{display:flex}.result-card{width:min(420px,90vw);padding:35px;background:linear-gradient(145deg,#17252a,#0a1519);border:1px solid #ffffff23;text-align:center;box-shadow:0 24px 80px #0008}.result-card .eyebrow{justify-content:center}.result-card h2{font:800 50px/.95 'Barlow Condensed';margin:14px 0 9px}.result-card p{color:#aab7b1;font-size:11px;margin:0 0 23px}.result-card .primary-btn{width:100%;margin-top:20px}.result-card .ghost-btn{justify-content:center;width:100%;margin-top:4px}.result-stats{display:flex;justify-content:space-around;border-block:1px solid var(--line);padding:13px 0}.result-stats div{display:flex;flex-direction:column;gap:5px}.result-stats small{font-size:7px;letter-spacing:1px;color:#aab7b1}.result-stats b{font:600 18px 'Barlow Condensed';color:var(--acid)}.toast{position:absolute;z-index:20;bottom:94px;left:50%;transform:translate(-50%,10px);opacity:0;background:#e7f3dc;color:#152019;padding:10px 18px;font-size:10px;font-weight:700;letter-spacing:.3px;transition:.3s;pointer-events:none;white-space:nowrap}.toast.show{opacity:1;transform:translate(-50%,0)}
@media(max-width:850px){.topbar{padding:0 4%;gap:16px}.player-progress{min-width:0}.xp-copy{display:none}.wallet{gap:9px}.home-copy{left:6%;top:23%;width:53vw}.home-copy h1{font-size:clamp(58px,11vw,90px)}.bike-label{right:4%;bottom:18%}.main-nav{gap:15px}.panel-screen{padding:110px 5% 40px}.level-grid{grid-template-columns:repeat(10,1fr);gap:4px}.level-card b{font-size:17px}.stage-tab{padding:9px 10px}.garage-layout{gap:3%}.shop-grid{grid-template-columns:repeat(5,1fr)}.shop-card{padding:9px;min-height:145px}.hub-grid{gap:8px}.hub-card{padding:15px}.game-bottom{gap:14px}.nitro-wrap{width:135px}}@media(max-width:620px){#app{min-height:480px}.topbar{height:65px;padding:0 15px;gap:10px}.brand-mark{width:30px;height:30px;font-size:11px}.brand-name{font-size:10px;letter-spacing:1.3px}.brand-name small{font-size:6px;letter-spacing:2px}.player-progress{gap:6px}.player-progress .avatar{width:26px;height:26px}.player-line{font-size:8px;gap:8px}.xp-track{width:65px}.wallet{gap:8px}.wallet-item{font-size:10px;gap:4px}.plus-btn{width:18px;height:18px;font-size:15px}.sound-toggle{display:none}.home-shade{background:linear-gradient(90deg,rgba(4,12,16,.88),rgba(4,12,16,.32)),linear-gradient(0deg,#071116 0,transparent 30%)}.home-copy{left:7%;top:18%;width:80vw}.home-copy h1{font-size:clamp(64px,18vw,90px);margin:18px 0 12px}.home-copy p{font-size:10px;margin-bottom:20px}.home-actions{gap:7px}.primary-btn{min-width:165px;height:45px;padding:0 12px;font-size:9px}.ghost-btn{font-size:8px;gap:6px;padding:0 7px}.season-line{margin-top:26px;width:min(310px,80vw)}.bike-label{bottom:96px;right:5%;gap:7px}.bike-number{font-size:28px;padding-right:8px}.bike-label h2{font-size:17px}.bike-label small,.bike-class{font-size:7px}.round-arrow{height:29px;width:29px}.main-nav{height:66px;gap:0;justify-content:space-around}.nav-item{min-width:45px;font-size:7px;letter-spacing:.7px}.nav-icon{font-size:14px}.panel-screen{padding:88px 16px 75px}.panel-heading{margin-bottom:18px}.panel-heading h2{font-size:43px}.panel-heading p{font-size:9px;max-width:290px}.stage-tabs{overflow-x:auto}.stage-tab{min-width:105px;font-size:8px;padding:8px}.level-grid{grid-template-columns:repeat(5,1fr);gap:5px}.level-card{aspect-ratio:1.5}.career-footer{font-size:8px;margin-top:16px}.career-footer .compact{min-width:127px}.garage-layout{height:auto;min-height:0;display:block}.garage-stage{height:270px;min-height:270px}.bike-details{padding:15px 3px}.bike-stat{} .stats-list{margin:10px 0 15px}.stat-row{margin:7px 0}.upgrade-list{gap:6px}.shop-grid{grid-template-columns:repeat(2,1fr);gap:8px}.shop-card{min-height:150px}.shop-bike-art{height:62px}.mission-list{grid-template-columns:1fr;gap:8px}.mission-card{min-height:115px;padding:13px}.achievement-card{padding:12px;gap:9px}.achievement-card span{font-size:8px}.achievement-progress{width:65px}.hub-grid{grid-template-columns:1fr}.hub-card{min-height:235px}.settings-card{min-height:280px}.game-top{top:73px;left:4%;right:4%;gap:8px}.game-pause{width:31px;height:31px}.run-objective{width:135px}.run-objective b{font-size:13px}.run-score b{font-size:23px}.game-left{left:4%;top:35%}.distance-box{padding:7px 9px}.distance-box b{font-size:20px}.game-bottom{left:4%;right:4%;bottom:12px;gap:8px;flex-wrap:wrap;align-items:flex-end}.speed-dial{width:67px;height:67px}.speed-dial b{font-size:29px}.run-coins{margin-bottom:4px;gap:4px}.run-coins small{display:none}.run-coins b{font-size:18px}.nitro-wrap{width:105px;margin-bottom:4px;margin-left:auto}.touch-controls{gap:6px;margin-left:0}.touch-controls button{width:51px;height:54px}.nitro-wrap button{padding:5px 7px}.result-card{padding:26px}.result-card h2{font-size:44px}}
