(() => {
'use strict';
const $=s=>document.querySelector(s), $$=s=>[...document.querySelectorAll(s)];
const canvas=$('#world'),ctx=canvas.getContext('2d');
const stages=[
 {name:'BEGINNER HIGHWAY',short:'BEGINNER',world:'COUNTRYSIDE',desc:'Easy traffic · Daylight',unlock:'STREET 150 · SPORT 250'},
 {name:'CITY TRAFFIC',short:'CITY',world:'INDIAN CITY',desc:'Dense traffic · Intersections',unlock:'NINJA ZX · RACING R6'},
 {name:'MOUNTAIN PASS',short:'MOUNTAIN',world:'MOUNTAIN',desc:'Curves · Tunnels · Elevation',unlock:'KTM DUKE · ADVENTURE 900'},
 {name:'NIGHT HIGHWAY',short:'NIGHT',world:'NIGHT EXPRESSWAY',desc:'Rain · Fog · Low visibility',unlock:'DUCATI V4 · BMW S1000RR'},
 {name:'EXTREME HIGHWAY',short:'EXTREME',world:'DESERT',desc:'Extreme density · Dynamic weather',unlock:'HAYABUSA · HYPER BEAST 1400'}
];
const bikes=[
 {name:'Street 150',class:'URBAN / CLASSIC',color:'#ef6338',price:0,unlock:1,speed:145,accel:55,handling:72,brake:62,engine:'single',rating:'1.8'},
 {name:'Sport 250',class:'SPORT / LIGHTWEIGHT',color:'#d9e548',price:1800,unlock:4,speed:185,accel:69,handling:78,brake:68,engine:'twin',rating:'2.6'},
 {name:'Ninja ZX',class:'SPORT / TRACK',color:'#42c97b',price:5200,unlock:12,speed:235,accel:76,handling:74,brake:74,engine:'inline',rating:'3.4'},
 {name:'Racing R6',class:'RACE / CIRCUIT',color:'#42b8ee',price:9000,unlock:16,speed:260,accel:84,handling:82,brake:83,engine:'race',rating:'4.0'},
 {name:'Ducati V4',class:'ITALIAN / SUPERBIKE',color:'#e84b42',price:14000,unlock:32,speed:285,accel:91,handling:80,brake:88,engine:'v4',rating:'4.6'},
 {name:'BMW S1000RR',class:'GERMAN / SUPERBIKE',color:'#f4f3e8',price:16800,unlock:36,speed:292,accel:88,handling:87,brake:92,engine:'race',rating:'4.8'},
 {name:'Hayabusa',class:'HYPER / GT',color:'#bb5bf0',price:22000,unlock:41,speed:315,accel:93,handling:76,brake:84,engine:'v4',rating:'4.9'},
 {name:'KTM Duke',class:'NAKED / STREET',color:'#ff842e',price:7600,unlock:23,speed:210,accel:81,handling:93,brake:79,engine:'twin',rating:'3.8'},
 {name:'Adventure 900',class:'ADVENTURE / TOUR',color:'#e7b936',price:11200,unlock:27,speed:220,accel:73,handling:85,brake:86,engine:'twin',rating:'4.1'},
 {name:'Hyper Beast 1400',class:'LEGENDARY / HYPER',color:'#fa3d4c',price:36000,unlock:46,speed:340,accel:98,handling:90,brake:95,engine:'v4',rating:'5.0'}
];
const defaults={coins:2450,gems:18,xp:0,level:1,bike:0,owned:[0],upgrades:[0,0,0,0],color:0,completed:0,best:0,daily:false,missions:{distance:0,overtake:0,nitro:0},clean:0};
let save;try{save={...defaults,...JSON.parse(localStorage.getItem('hr-save')||'{}')};}catch{save={...defaults};}
save.owned=save.owned||[0];save.upgrades=save.upgrades||[0,0,0,0];save.missions=save.missions||{distance:0,overtake:0,nitro:0};
const paintColors=['#ef6338','#e7e548','#45c8ea','#e8ece8','#a85ef1','#67d47d'];
let screen='home',activeStage=0,selectedLevel=1,rideMode='career',running=false,paused=false,gameOver=false;
let w=innerWidth,h=innerHeight,dpr=1,lastTime=0,clock=0,spawnTimer=0,traffic=[],particles=[],playerX=0,targetX=0,speed=0,distance=0,score=0,earned=0,nitro=100,nitroActive=false,steer=0,braking=false,accelerating=false,engineAudio=null, soundOn=true,viewMode='chase',runGoal=1200,runTargetOvertakes=8,overtakes=0,runCompleted=false,toastTimer=0,nearTimer=0,rideStart=0,rideStartDistance=0, environmentOverride='Auto rotation', menuCamera=0, pointerX=null;
function persist(){localStorage.setItem('hr-save',JSON.stringify(save));updateTop();}
function updateTop(){ $('#coin-count').textContent=save.coins.toLocaleString();$('#gem-count').textContent=save.gems;$('#level-label').textContent=`LVL ${String(save.level).padStart(2,'0')}`;$('#xp-copy').textContent=`${save.xp%500} / 500 XP`;$('#xp-fill').style.width=`${(save.xp%500)/5}%`;$('#home-bike-name').textContent=bikes[save.bike].name.toUpperCase();$('#best-score').textContent=save.best.toLocaleString(); }
function notify(msg){const t=$('#toast');t.textContent=msg;t.classList.add('show');clearTimeout(toastTimer);toastTimer=setTimeout(()=>t.classList.remove('show'),2300)}
function resize(){w=innerWidth;h=innerHeight;dpr=Math.min(devicePixelRatio||1,2);canvas.width=Math.floor(w*dpr);canvas.height=Math.floor(h*dpr);canvas.style.width=w+'px';canvas.style.height=h+'px';ctx.setTransform(dpr,0,0,dpr,0,0)}addEventListener('resize',resize);resize();
function envForRun(){if(environmentOverride!=='Auto rotation'){return ['Indian city','Countryside','Mountain pass','Desert run','Night expressway'].indexOf(environmentOverride)}return rideMode==='career'?Math.floor((selectedLevel-1)/10):Math.floor(Math.random()*5)}
function stageIndex(level){return Math.min(4,Math.floor((level-1)/10))}
function createCareer(){const tabs=$('#stage-tabs');tabs.innerHTML='';stages.forEach((s,i)=>{const b=document.createElement('button');b.className='stage-tab'+(i===activeStage?' active':'');b.innerHTML=`<b>0${i+1} / ${s.short}</b>${s.desc}`;b.onclick=()=>{activeStage=i;selectedLevel=Math.max(i*10+1,Math.min(save.completed+1,i*10+10));createCareer()};tabs.append(b)});$('#next-stage-name').textContent=stages[activeStage].name;const grid=$('#level-grid');grid.innerHTML='';for(let i=activeStage*10+1;i<=activeStage*10+10;i++){let card=document.createElement('button');let complete=i<=save.completed,locked=i>save.completed+1;card.className='level-card'+(complete?' complete':'')+(locked?' locked':'')+(i===selectedLevel?' current':'');card.innerHTML=`<b>${String(i).padStart(2,'0')}</b><span>${complete?'★ DONE':locked?'LOCKED':'RIDE'}</span>`;card.onclick=()=>{if(locked){notify('Complete the previous ride to unlock this level');return}selectedLevel=i;createCareer()};grid.append(card)}$('#career-ride').querySelector('span').textContent=`RIDE LEVEL ${String(selectedLevel).padStart(2,'0')}`}
function bikeStats(){const b=bikes[save.bike];$('#bike-bike-title');$('#garage-bike-title').textContent=b.name.toUpperCase();$('#garage-bike-index').textContent=`${String(save.bike+1).padStart(2,'0')} — ${b.class}`;$('#bike-rating').textContent=`★ ${b.rating}`;const levels=save.upgrades;const names=['TOP SPEED','ACCELERATION','HANDLING','BRAKING'];const values=[b.speed,b.accel,b.handling,b.brake];$('#bike-stats').innerHTML=names.map((n,i)=>`<div class="stat-row"><span>${n}</span><div class="stat-bar"><i style="width:${Math.min(100,values[i]+(i<4?levels[i]*4:0))}%"></i></div><strong>${Math.min(100,values[i]+levels[i]*4)}</strong></div>`).join('');const uNames=['ENGINE','BRAKES','HANDLING','NITRO'];$('#upgrade-list').innerHTML=uNames.map((n,i)=>`<div class="upgrade-item"><strong>${n}</strong><span class="upgrade-dots">${[1,2,3,4,5].map(x=>`<i class="${x<=Math.max(1,levels[i]+1)?'on':''}"></i>`).join('')}</span></div>`).join('');$('#upgrade-tier').textContent=String(Math.max(...levels)+1).padStart(2,'0');$('#upgrade-price').textContent=(250+Math.max(...levels)*400).toLocaleString();$('#color-swatches').innerHTML=paintColors.map((c,i)=>`<button class="swatch ${i===save.color?'active':''}" data-color="${i}" style="background:${c}" aria-label="Paint ${i+1}"></button>`).join('');$$('.swatch').forEach(el=>el.onclick=()=>{save.color=+el.dataset.color;persist();bikeStats()})}
function createShop(){const grid=$('#shop-grid');grid.innerHTML='';bikes.forEach((b,i)=>{const owned=save.owned.includes(i),locked=save.level<b.unlock;const card=document.createElement('article');card.className='shop-card'+(owned?' owned':'')+(i===save.bike?' selected':'');card.innerHTML=`<div class="shop-bike-art" style="--bike-color:${b.color}">♞</div><small>${String(i+1).padStart(2,'0')} · ${b.class}</small><h3>${b.name.toUpperCase()}</h3><div class="shop-meta"><span>${owned?'OWNED':locked?`LVL ${b.unlock} REQUIRED`:`¢ ${b.price.toLocaleString()}`}</span><button>${owned?(i===save.bike?'RIDE':'SELECT'):locked?'LOCKED':'UNLOCK'}</button></div>`;card.querySelector('button').onclick=()=>{if(owned){save.bike=i;persist();createShop();bikeStats();notify(`${b.name} selected`)}else if(locked){notify(`Reach rider level ${b.unlock} to unlock this bike`)}else if(save.coins>=b.price){save.coins-=b.price;save.owned.push(i);save.bike=i;persist();createShop();bikeStats();notify(`${b.name} unlocked — welcome to the garage!`)}else notify('Not enough coins — hit the road for more')};grid.append(card)})}
const missions=[{key:'distance',name:'MILE MAKER',text:'Travel 3 km across any ride.',goal:3000,reward:450,icon:'◷'},{key:'overtake',name:'OPEN ROAD',text:'Pass 15 vehicles cleanly.',goal:15,reward:600,icon:'↗'},{key:'nitro',name:'AFTERBURN',text:'Use nitro for a total of 20 sec.',goal:20,reward:500,icon:'ϟ'}];
function createMissions(){const box=$('#mission-list');box.innerHTML='';missions.forEach(m=>{const val=save.missions[m.key]||0,done=val>=m.goal;const card=document.createElement('article');card.className='mission-card';card.innerHTML=`<div class="mission-top"><span>${m.icon} &nbsp; DAILY CONTRACT</span><span class="mission-reward">+${m.reward} ¢</span></div><h3>${m.name}</h3><p>${m.text}</p><div class="mission-bottom"><div class="mission-bar"><i style="width:${Math.min(100,val/m.goal*100)}%"></i></div><b>${Math.min(val,m.goal)} / ${m.goal}${m.key==='distance'?' m':m.key==='nitro'?' sec':''}</b><button class="switch ${done?'on':''}" data-claim="${m.key}" ${done?'':'disabled'}>${done?'CLAIM':'···'}</button></div>`;card.querySelector('button').onclick=()=>{if(done&&!save['claim_'+m.key]){save['claim_'+m.key]=true;save.coins+=m.reward;persist();createMissions();notify(`Mission complete · +${m.reward} coins`)}};box.append(card)});$('#achievement-progress').textContent=`${Math.min(save.clean,10)} / 10`;$('#achievement-fill').style.width=`${Math.min(100,save.clean*10)}%`}
function setScreen(name){screen=name;$$('.screen').forEach(s=>s.classList.remove('active'));$('#game-screen').classList.remove('active');if(name==='game'){$('#game-screen').classList.add('active')}else{$(`#${name}-screen`)?.classList.add('active')}$$('.nav-item').forEach(b=>b.classList.toggle('selected',b.dataset.screen===name));if(name==='career')createCareer();if(name==='garage')bikeStats();if(name==='shop')createShop();if(name==='missions')createMissions()}
$$('[data-screen]').forEach(b=>b.addEventListener('click',()=>setScreen(b.dataset.screen)));
$$('[data-action]').forEach(b=>b.addEventListener('click',()=>startRide(b.dataset.action==='career'?'career':'endless')));
$('#career-ride').onclick=()=>startRide('career');
$('#bike-prev').onclick=()=>cycleBike(-1);$('#bike-next').onclick=()=>cycleBike(1);
function cycleBike(d){let n=save.bike;for(let i=0;i<bikes.length;i++){n=(n+d+bikes.length)%bikes.length;if(save.owned.includes(n)){save.bike=n;break}}persist();bikeStats()}
$('#upgrade-bike').onclick=()=>{const price=250+Math.max(...save.upgrades)*400;if(save.coins<price){notify('Not enough coins for this upgrade');return}if(Math.max(...save.upgrades)>=5){notify('All systems are maxed out');return}save.coins-=price;const i=save.upgrades.indexOf(Math.min(...save.upgrades));save.upgrades[i]++;persist();bikeStats();notify('Machine tuned · upgrade installed')};
$('#claim-daily').onclick=()=>{if(save.daily){notify('Daily reward already claimed — see you tomorrow!');return}save.daily=true;save.coins+=300;persist();$('#claim-daily').querySelector('span').textContent='CLAIMED · COME BACK TOMORROW';notify('Daily drop claimed · +300 coins')};
$('#camera-setting').onchange=e=>{viewMode=e.target.value;notify(viewMode==='chase'?'Chase camera selected':'Rider camera selected')};$('#environment-setting').onchange=e=>environmentOverride=e.target.value;
['audio-setting','vibration-setting'].forEach(id=>$('#'+id).onclick=e=>{e.currentTarget.classList.toggle('on');e.currentTarget.textContent=e.currentTarget.classList.contains('on')?'ON':'OFF';if(id==='audio-setting')soundOn=e.currentTarget.classList.contains('on')});
$('#sound-toggle').onclick=()=>{soundOn=!soundOn;$('#sound-toggle').style.opacity=soundOn?'1':'.45';if(engineAudio)engineAudio.gain.gain.value=soundOn?.04:0;notify(soundOn?'Audio on':'Audio muted')};$('#exit-game').onclick=()=>notify('Thanks for riding with us!');
function startRide(mode){rideMode=mode;const st=stageIndex(selectedLevel);runGoal=mode==='career'?1000+selectedLevel*200:0;runTargetOvertakes=mode==='career'?Math.max(5,Math.round(7+selectedLevel*.45)):0;distance=0;speed=0;score=0;earned=0;nitro=100;traffic=[];particles=[];spawnTimer=.5;playerX=targetX=0;overtakes=0;runCompleted=false;gameOver=false;paused=false;running=true;rideStart=performance.now();rideStartDistance=0;envIndex=envForRun();$('#run-mode-label').textContent=mode==='career'?`CAREER · LEVEL ${String(selectedLevel).padStart(2,'0')}`:mode==='trial'?'TIME TRIAL · 90 SEC':'ENDLESS · OPEN ROAD';$('#run-objective-text').textContent=mode==='career'?`RIDE ${(runGoal).toLocaleString()} m`:mode==='trial'?'SCORE BIG · 90 SEC':'OVERTAKE & SURVIVE';$('#pause-overlay').classList.remove('visible');$('#result-overlay').classList.remove('visible');setScreen('game');initAudio();lastTime=performance.now();notifyGame(`STAGE 0${st+1} · ${stages[st].world}`)}let envIndex=0;
