function syncSettings(){$('camera-setting').value=save.camera;$('environment-setting').selectedIndex=save.environment;$('audio-setting').classList.toggle('on',save.audio);$('audio-setting').textContent=save.audio?'ON':'OFF';$('vibration-setting').classList.toggle('on',save.vibration);$('vibration-setting').textContent=save.vibration?'ON':'OFF';}

function startRide(which='career',whichLevel=save.unlocked){mode=which;level=whichLevel;envIndex=which==='career'?Math.floor((level-1)/10):save.environment?save.environment-1:Math.floor(Math.random()*5);if(envIndex<0)envIndex=0;traffic=[];playerX=0;speed=0;nitro=100;score=0;rideCoins=0;distance=0;rideTime=0;spawnTimer=.45;paused=false;running=true;gameOver=false;boosting=false;accelerating=true;braking=false;$('pause-overlay').classList.remove('visible');$('result-overlay').classList.remove('visible');$('game-screen').classList.add('active');$('game-screen').style.display='block';screen='game';const labels={career:`CAREER · LEVEL ${String(level).padStart(2,'0')}`,endless:'ENDLESS · OPEN ROAD',trial:'TIME TRIAL · 90 SECONDS'};$('run-mode-label').textContent=labels[mode];$('run-objective-text').textContent=mode==='career'?`RIDE ${800+level*80} m`:mode==='trial'?'SCORE BIG IN 90 SECONDS':'RIDE AS FAR AS YOU CAN';$('objective-fill').style.width='0%';showToast(mode==='trial'?'90 seconds. Make every pass count.':'Find your line and own the road.');}
function endRide(success=false){if(gameOver)return;gameOver=true;running=false;paused=false;accelerating=false;braking=false;const reward=Math.max(25,Math.round(rideCoins+(score/120)+(success?100:0)));save.coins+=reward;save.xp+=Math.max(20,Math.floor(distance*3));while(save.xp>=500){save.xp-=500;save.level++;save.coins+=250;showToast('RIDER LEVEL UP · +250 ¢');}save.best=Math.max(save.best,Math.floor(score));if(mode==='career'&&success){if(!save.completed.includes(level))save.completed.push(level);save.unlocked=Math.max(save.unlocked,Math.min(50,level+1));}persist();$('result-eyebrow').textContent=success?'RIDE COMPLETE':'RUN ENDED';$('result-title').innerHTML=success?'NICE <em>RUN.</em>':'ROAD <em>WARRIOR.</em>';$('result-copy').textContent=success?'Another chapter in the making. Keep the momentum.':'Every ride makes you quicker. Ready for another?';$('result-score').textContent=fmt(score);$('result-distance').textContent=`${(distance/1000).toFixed(1)} km`;$('result-reward').textContent=`+${fmt(reward)} ¢`;$('result-overlay').classList.add('visible');}
function pauseRide(){if(!running||gameOver)return;paused=true;accelerating=false;braking=false;$('pause-overlay').classList.add('visible');}
function resumeRide(){paused=false;$('pause-overlay').classList.remove('visible');}
function updateGame(dt){rideTime+=dt;const b=bikes[save.bike],upgrade=save.upgrades[save.bike]||0,maxSpeed=b.speed+upgrade*8;const target=accelerating?maxSpeed*.82:braking?24:Math.max(0,maxSpeed*.45);speed+=(target-speed)*Math.min(1,dt*(accelerating?1.8:braking?3:0.45));if(boosting&&nitro>0){speed=Math.min(maxSpeed*1.22,speed+70*dt);nitro=Math.max(0,nitro-22*dt);score+=Math.round(45*dt);}else nitro=Math.min(100,nitro+3.4*dt);const kmh=speed;distance+=kmh/3.6*dt;roadOffset=(roadOffset+kmh*dt*.55)%100;score+=Math.floor(kmh*dt*.52);spawnTimer-=dt;if(spawnTimer<=0){traffic.push({x:(Math.random()*1.55-.775),z:0,type:Math.random()<.18?'truck':'car',color:['#e8b04e','#7bb0a0','#d96a56','#b2a7d0','#d4d7c8'][Math.floor(Math.random()*5)],passed:false});spawnTimer=Math.max(.48,1.35-Math.min(.55,kmh/450))*(.72+Math.random()*.7);}const playerLane=playerX;for(const car of traffic){car.z+=dt*(.20+kmh/900);if(!car.passed&&car.z>.84){car.passed=true;if(Math.abs(car.x-playerLane)<.2){if(Math.abs(car.x-playerLane)<.105){speed*=.48;score=Math.max(0,score-300);showGameToast('COLLISION · WATCH YOUR LINE');if(speed<23&&Math.random()<.28)endRide(false);}else{score+=250;rideCoins+=5;save.cleanPasses++;nearTimer=1.2;showGameToast('NEAR MISS · +250');}}else{score+=90;save.cleanPasses++;}}}traffic=traffic.filter(c=>c.z<1.3);if(mode==='career'&&distance>=800+level*80)endRide(true);if(mode==='trial'&&rideTime>=90)endRide(true);if(nearTimer>0)nearTimer-=dt;updateHud();}
function updateHud(){ $('run-score').textContent=String(Math.floor(score)).padStart(6,'0');$('distance-value').textContent=(distance/1000).toFixed(1);$('speed-value').textContent=Math.round(speed);$('gear-value').textContent=speed<5?'N':String(clamp(Math.floor(speed/35)+1,1,6));$('run-coins').textContent=rideCoins;$('nitro-value').textContent=`${Math.round(nitro)}%`;$('nitro-fill').style.width=`${nitro}%`;$('near-miss').classList.toggle('show',nearTimer>0);const objective=mode==='career'?800+level*80:mode==='trial'?90:3000;$('objective-fill').style.width=`${clamp((mode==='trial'?rideTime/90:distance/objective)*100,0,100)}%`;}
function showGameToast(text){const el=$('game-toast');el.textContent=text;el.classList.add('show');setTimeout(()=>el.classList.remove('show'),900);}

