document.addEventListener('click',e=>{const action=e.target.closest('[data-action]')?.dataset.action;if(action){if(action==='career')setScreen('career');else startRide(action);return;}const target=e.target.closest('[data-screen]');if(target){setScreen(target.dataset.screen);return;}const tile=e.target.closest('[data-level]');if(tile&&!tile.disabled){const n=Number(tile.dataset.level);startRide('career',n);return;}const stage=e.target.closest('[data-stage]');if(stage){const n=Number(stage.dataset.stage);const first=n*10+1;if(first>save.unlocked){showToast('Finish the previous stage to unlock this road.');return;}document.querySelectorAll('.stage-tab').forEach(el=>el.classList.toggle('selected',el===stage));document.querySelectorAll('.level-tile').forEach(el=>{const n=Number(el.dataset.level);el.hidden=Math.floor((n-1)/10)!==Number(stage.dataset.stage);});return;}const color=e.target.closest('[data-color]');if(color){save.color=Number(color.dataset.color);persist();renderGarage();return;}const shop=e.target.closest('[data-bike]');if(shop){const i=Number(shop.dataset.bike);if(save.owned.includes(i)){save.bike=i;renderShop();renderGarage();persist();}else if(save.coins>=bikes[i].price){save.coins-=bikes[i].price;save.owned.push(i);save.bike=i;persist();renderShop();renderGarage();showToast(`${bikes[i].name} added to your garage.`);}else showToast('Not enough coins yet. Ride to earn more.');return;}const mission=e.target.closest('[data-mission]');if(mission&&!mission.disabled){const i=Number(mission.dataset.mission);const rewards=[180,250,300];save.missions[i]=1;save.coins+=rewards[i];persist();renderMissions();showToast(`MISSION COMPLETE · +${rewards[i]} ¢`);return;}});
