@import url('https://fonts.googleapis.com/css2?family=Barlow+Condensed:wght@500;600;700;800;900&family=DM+Sans:wght@400;500;600;700;800&display=swap');
:root{--ink:#071116;--panel:#0b171bcc;--line:#ffffff25;--paper:#edf0e7;--muted:#aab8b1;--acid:#d8e94e;--orange:#f0784e;--font-head:'Barlow Condensed',Impact,sans-serif;--font-body:'DM Sans',Arial,sans-serif}*{box-sizing:border-box}html,body{margin:0;width:100%;height:100%;overflow:hidden;background:var(--ink);color:var(--paper);font-family:var(--font-body)}button,select{font:inherit;color:inherit}button{cursor:pointer}#app{position:relative;width:100%;height:100%;min-height:540px;overflow:hidden;background:#16252a}#world{position:absolute;inset:0;width:100%;height:100%;z-index:0}.vignette{position:absolute;inset:0;pointer-events:none;z-index:1;background:linear-gradient(90deg,#061014aa,transparent 58%),linear-gradient(0deg,#061014dd,transparent 28%,#06101444)}.topbar{position:absolute;z-index:8;top:0;left:0;right:0;height:78px;padding:13px 4.7%;display:flex;align-items:center;gap:25px;border-bottom:1px solid #ffffff20;background:linear-gradient(#071116c9,#07111645)}.brand{display:flex;align-items:center;gap:10px;border:0;background:none;text-align:left;padding:0}.brand-mark{display:grid;place-items:center;width:39px;height:39px;background:var(--acid);color:#152022;font:900 19px var(--font-head);transform:skew(-7deg)}.brand-mark span{color:var(--orange)}.brand-name{font:700 14px var(--font-head);letter-spacing:1.5px}.brand-name b{color:var(--acid)}.brand-name small{display:block;color:#aab8b1;font:600 8px var(--font-body);letter-spacing:2.2px;margin-top:1px}.player-progress{display:flex;align-items:center;gap:9px;margin-left:auto;min-width:215px}.avatar,.leader-avatar{display:grid;place-items:center;width:31px;height:31px;border:1px solid var(--acid);border-radius:50%;font-weight:800;color:var(--acid)}.player-line{display:flex;gap:12px;font-size:9px;letter-spacing:1px;white-space:nowrap}.player-line span{color:var(--acid)}.xp-track{width:128px;height:3px;background:#ffffff35;margin-top:6px}.xp-track i{display:block;width:0;height:100%;background:var(--acid)}.xp-copy{color:#aab8b1;font-size:9px;white-space:nowrap}.wallet{display:flex;gap:14px;align-items:center}.wallet-item{font-size:12px;display:flex;gap:6px;align-items:center}.coin-icon,.gem-icon{font-style:normal;color:var(--acid);font-size:14px}.gem-icon{color:#6dd5dc}.plus-btn{border:1px solid #ffffff40;width:27px;height:27px;border-radius:50%;background:#ffffff12;color:var(--acid);font-size:20px;line-height:20px}.icon-btn{border:1px solid #ffffff36;background:#07111655;border-radius:50%;width:32px;height:32px}.icon-btn.muted{opacity:.5}.screen{position:absolute;inset:0;z-index:3;display:none}.screen.active{display:block}.home-shade{position:absolute;inset:0;background:linear-gradient(90deg,#071116eb 0%,#0711169c 42%,transparent 78%),linear-gradient(0deg,#071116df,transparent 38%)}.home-copy{position:absolute;left:8.4%;top:19%;max-width:470px}.eyebrow{font-size:9px;font-weight:700;letter-spacing:2px;color:var(--acid);display:flex;align-items:center;gap:9px}.live-dot{display:inline-block;width:6px;height:6px;border-radius:50%;background:var(--acid);box-shadow:0 0 11px var(--acid)}.eyebrow i{width:28px;height:1px;background:#ffffff70}.home-copy h1,.panel-heading h2{margin:15px 0 8px;font:900 clamp(53px,7vw,91px)/.82 var(--font-head);letter-spacing:-1px}.home-copy h1 em,.panel-heading h2 em,.result-card h2 em{font-style:normal;color:var(--acid)}.home-copy>p,.panel-heading p{font-size:12px;color:#c1cbc4;line-height:1.7}.home-actions{display:flex;align-items:center;gap:12px;flex-wrap:wrap;margin-top:28px}.primary-btn,.ghost-btn{display:flex;align-items:center;justify-content:space-between;gap:18px;border:1px solid var(--acid);background:var(--acid);color:#111b1b;padding:13px 16px;min-width:176px;font-size:10px;font-weight:800;letter-spacing:1.2px;text-align:left;transition:.18s}.primary-btn b{font-size:18px}.primary-btn:hover{background:#eef799;transform:translateY(-2px)}.ghost-btn{min-width:auto;background:#0813188c;color:var(--paper);border-color:#ffffff43;padding:12px 15px}.g