 function syncSettings(){$('camera-setting').value=save.camera;$('environment-setting').selectedIndex=save.environment;$('audio-setting').classList.toggle('on',save.audio);$('audio-setting').textContent=save.audio?'ON':'OFF';$('vibration-setting').classList.toggle('on',save.vibration);$('vibration-setting').textContent=save.vibration?'ON':'OFF';}

 function startRide(which='career',whichLevel=save.unlocked){mode=which;level=whichLevel;envIndex=which==='career'?Math.floor((level-1)/10):save.environment?save.environment-1:Math.floor(Math.random()*5);if(envIndex<0)envIndex=0;traffic=[];playerX=0;speed=0;nitro=100;score=0;rideCoins=0;distance=0;rideTime=0;spawnTimer=.45;paused=false;running=true;gameOver=false;boosting=false;accelerating=true;braking=false;document.querySelectorAll('.screen').forEach(el=>el.classList.remove('active'));$('pause-overlay').classList.remove('visible');$('result-overlay').classList.remove('visible');$('game-screen').classList.add('active');$('game-screen').style.display='block';screen='game';const labels={career:`CAREER · LEVEL ${String(level).padStart(2,'0')}`,endless:'ENDLESS · OPEN ROAD',trial:'TIME TRIAL · 90 SECONDS'};$('run-mode-label').textContent=labels[mode];$('run-objective-text').textContent=mode==='career'?`RIDE ${800+level*80} m`:mode==='trial'?'SCORE BIG IN 90 SECONDS':'RIDE AS FAR AS YOU CAN';$('objective-fill').style.width='0%';showToast(mode==='trial'?'90 seconds. Make every pass count.':'Find your line and own the road.');}
 function endRide(success=false){if(gameOver)return;gameOver=true;running=false;paused=false;accelerating=false;braking=false;const reward=Math.max(25,Math.round(rideCoins+(score/120)+(success?100:0)));save.coins+=reward;save.totalDistance=(save.totalDistance||0)+distance;save.xp+=Math.max(20,Math.floor(distance*3));while(save.xp>=500){save.xp-=500;save.level++;save.coins+=250;showToast('RIDER LEVEL UP · +250 ¢');}save.best=Math.max(save.best,Math.floor(score));if(mode==='career'&&success){if(!save.completed.includes(level))save.completed.push(level);save.unlocked=Math.max(save.unlocked,Math.min(50,level+1));}persist();$('result-eyebrow').textContent=success?'RIDE COMPLETE':'RUN ENDED';$('result-title').innerHTML=success?'NICE <em>RUN.</em>':'ROAD <em>WARRIOR.</em>';$('result-copy').textContent=success?'Another chapter in the making. Keep the momentum.':'Every ride makes you quicker. Ready for another?';$('result-score').textContent=fmt(score);$('result-distance').textContent=`${(distance/1000).toFixed(1)} km`;$('result-reward').textContent=`+${fmt(reward)} ¢`;$('result-overlay').classList.add('visible');}
